const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbyEG1A2-UMrsSlERt6Y643SMsS0WoGyKxdY71wlpgB6J70DjYwn4Z9VDmY0bTNS3ULkZw/exec";

const grid = document.getElementById('grid');
const qtyState = {};

function render(list){
  grid.innerHTML = '';
  if(list.length === 0){
    grid.innerHTML = '<div class="empty">Hech narsa topilmadi</div>';
    return;
  }
  list.forEach(p => {
    const card = document.createElement('div');
    card.className = 'card';
    const qty = qtyState[p.code] || 0;
    card.innerHTML = `
      <img src="data:image/jpeg;base64,${p.img}" loading="lazy" alt="${p.code}">
      <div class="code">${p.code}</div>
      <div class="qty">
        <button class="minus">-</button>
        <input type="number" min="0" value="${qty}" data-code="${p.code}">
        <button class="plus">+</button>
      </div>
    `;
    const input = card.querySelector('input');
    card.querySelector('.minus').onclick = () => {
      input.value = Math.max(0, (parseInt(input.value)||0) - 1);
      updateQty(p.code, input.value);
    };
    card.querySelector('.plus').onclick = () => {
      input.value = (parseInt(input.value)||0) + 1;
      updateQty(p.code, input.value);
    };
    input.oninput = () => updateQty(p.code, input.value);
    grid.appendChild(card);
  });
}

function updateQty(code, val){
  const n = Math.max(0, parseInt(val)||0);
  if(n === 0) delete qtyState[code];
  else qtyState[code] = n;
  updateBar();
}

function updateBar(){
  const codes = Object.keys(qtyState);
  document.getElementById('count').textContent = codes.length + " ta mahsulot tanlandi";
  document.getElementById('orderBtn').disabled = codes.length === 0;
}

document.getElementById('search').addEventListener('input', (e) => {
  const q = e.target.value.trim().toUpperCase();
  const filtered = q ? PRODUCTS.filter(p => p.code.toUpperCase().includes(q)) : PRODUCTS;
  render(filtered);
});

render(PRODUCTS);

document.getElementById('orderBtn').onclick = () => {
  const name = document.getElementById('custName').value.trim();
  const phone = document.getElementById('custPhone').value.trim();
  if(!name || !phone){
    showToast("Iltimos, ism va telefon raqamingizni kiriting");
    return;
  }
  const rows = Object.entries(qtyState);
  if(rows.length === 0) return;
  document.getElementById('orderName').innerHTML = `<b>${name}</b>`;
  document.getElementById('orderPhone').textContent = phone;
  const table = document.getElementById('orderTable');
  table.innerHTML = rows.map(([code, qty]) => `<tr><td>${code}</td><td style="text-align:right">${qty} dona</td></tr>`).join('');
  document.getElementById('overlay').classList.add('show');
};

document.getElementById('cancelBtn').onclick = () => {
  document.getElementById('overlay').classList.remove('show');
};

document.getElementById('confirmBtn').onclick = async () => {
  const name = document.getElementById('custName').value.trim();
  const phone = document.getElementById('custPhone').value.trim();
  const items = Object.entries(qtyState).map(([code, qty]) => ({ nomi: code, miqdori: qty, birlik: "dona" }));
  const payload = { customerName: name, customerPhone: phone, items: items };

  document.getElementById('confirmBtn').textContent = "Yuborilmoqda...";
  document.getElementById('confirmBtn').disabled = true;

  try {
    await fetch(APPS_SCRIPT_URL, {
      method: 'POST',
      mode: 'no-cors',
      headers: { 'Content-Type': 'text/plain' },
      body: JSON.stringify(payload)
    });
    document.getElementById('overlay').classList.remove('show');
    showToast("Buyurtmangiz qabul qilindi! Rahmat.");
    Object.keys(qtyState).forEach(k => delete qtyState[k]);
    render(PRODUCTS);
    document.getElementById('search').value = '';
    updateBar();
  } catch(err){
    showToast("Xatolik yuz berdi, qayta urinib ko'ring");
  }
  document.getElementById('confirmBtn').textContent = "Tasdiqlayman";
  document.getElementById('confirmBtn').disabled = false;
};

function showToast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 2500);
}
